const revisionFile='assets/data/page-revisions.json';
const revisions=fs.existsSync(path.join(root,revisionFile))?JSON.parse(read(revisionFile)):{};
const contentDate=process.env.PPS_CONTENT_DATE||'2026-10-27';
const publicEntries=[...builtPages.entries()].filter(([,p])=>!p.noindex);
for(const [file]of publicEntries){const digest=crypto.createHash('sha256').update(read(file)).digest('hex');if(revisions[file]?.digest!==digest)revisions[file]={digest,lastmod:contentDate};}
write(revisionFile,JSON.stringify(revisions,null,2));
write('sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${publicEntries.map(([file,p])=>`  <url><loc>${p.url}</loc><lastmod>${revisions[file].lastmod}</lastmod></url>`).join('\n')}\n</urlset>\n`);
